    const outpoints = tx.ins.map((i) => i.outpoint.toString("hex")).sort().join(",");
    if (expected.some((e) => e.approved.btc_outpoints !== outpoints)) return "a cancellation must spend exactly the coins this approval already signed";
    return out;
