const COSMOS_DELEGATE = "/cosmos.staking.v1beta1.MsgDelegate";
const COSMOS_UNDELEGATE = "/cosmos.staking.v1beta1.MsgUndelegate";
const COSMOS_WITHDRAW_REWARD = "/cosmos.distribution.v1beta1.MsgWithdrawDelegatorReward";
